#!/usr/bin/env python3
"""
Analysis Script - Tecan Plate Reader Loading Isotherm Evaluation
Can be called externally with experiment ID as parameter.
"""

import os
import sys
import json
import argparse
import shutil
from pathlib import Path
from typing import Dict, Any, List, Tuple

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.optimize import curve_fit

import requests

# Device control server configuration for Tecan
DEVICE_CONTROL_SERVER = os.getenv('DEVICE_CONTROL_SERVER', 'http://localhost:8000')
DEVICE_API_KEY = os.getenv('DEVICE_API_KEY', 'your-secure-api-key-here')


def check_tecan_data_availability(experiment_id: str) -> dict:
    """Check if Tecan data is available for the given experiment ID."""
    url = f"{DEVICE_CONTROL_SERVER}/api/tecan/data/{experiment_id}/list"
    headers = {'X-API-Key': DEVICE_API_KEY}
    try:
        response = requests.get(url, headers=headers, timeout=10)
        if response.status_code == 200:
            data = response.json()
            return {"available": data.get('total_files', 0) > 0,
                    "total_files": data.get('total_files', 0),
                    "files": data.get('files', [])}
        elif response.status_code == 404:
            return {"available": False, "total_files": 0, "files": [], "error": "No data found"}
        else:
            return {"available": False, "total_files": 0, "files": [], "error": f"Server error: {response.status_code}"}
    except Exception as e:
        return {"available": False, "total_files": 0, "files": [], "error": str(e)}


def fetch_tecan_data_file(experiment_id: str, save_to_folder: str, file_index: int = 0) -> str:
    """Fetch a SINGLE Tecan Excel data file from device control server."""
    url = f"{DEVICE_CONTROL_SERVER}/api/tecan/data/{experiment_id}?file_index={file_index}"
    headers = {'X-API-Key': DEVICE_API_KEY}
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
        save_folder = Path(save_to_folder)
        save_folder.mkdir(parents=True, exist_ok=True)
        filename = f"tecan_data_{experiment_id}.xlsx"
        file_path = save_folder / filename
        with open(file_path, 'wb') as f:
            f.write(response.content)
        print(f"Successfully downloaded Tecan data to: {file_path}")
        return str(file_path)
    except requests.exceptions.ConnectionError:
        raise Exception(f"Cannot connect to device control server at {DEVICE_CONTROL_SERVER}")
    except requests.exceptions.Timeout:
        raise Exception("Timeout while fetching Tecan data from device control server")
    except Exception as e:
        raise Exception(f"Failed to fetch Tecan data for experiment {experiment_id}: {str(e)}")


def get_most_recent_folder(directory, n=0):
    """Finds the n-th most recent subfolder in a given directory."""
    folders = [f for f in os.listdir(directory) if os.path.isdir(os.path.join(directory, f))]
    if not folders:
        return None
    sorted_folders = sorted(folders, key=lambda f: os.path.getctime(os.path.join(directory, f)), reverse=True)
    return os.path.join(directory, sorted_folders[n]) if len(sorted_folders) > n else None


def get_most_recent_excel_file(directory, n=0):
    """Finds the most recent Excel file within the 'Export/xlsx/' subfolder."""
    most_recent_folder = get_most_recent_folder(directory, n)
    if not most_recent_folder:
        return None
    excel_export_path = Path(most_recent_folder) / "Export" / "xlsx"
    if not excel_export_path.exists() or not excel_export_path.is_dir():
        return None
    try:
        files_in_folder = os.listdir(excel_export_path)
        excel_files = [f for f in files_in_folder if f.lower().endswith('.xlsx')]
        if not excel_files:
            return None
        excel_files.sort(key=lambda f: os.path.getctime(Path(excel_export_path) / f), reverse=True)
        return str(Path(excel_export_path) / excel_files[0])
    except Exception:
        return None


def _langmuir_isotherm(c_e: np.ndarray, q_max: float, k_a: float) -> np.ndarray:
    """Langmuir isotherm: q = q_max * K * c_e / (1 + K * c_e)."""
    return q_max * k_a * c_e / (1.0 + k_a * c_e)


def _well_to_indices(well: str) -> Tuple[int, int]:
    """Convert well ID like 'A1' to (row_index, col_index) 0-based."""
    if not isinstance(well, str) or len(well) < 2:
        raise ValueError(f"Invalid well identifier: {well}")
    row_char = well[0].upper()
    if row_char < 'A' or row_char > 'H':
        raise ValueError(f"Row out of range in well identifier: {well}")
    try:
        col = int(well[1:])
    except ValueError:
        raise ValueError(f"Column not numeric in well identifier: {well}")
    if col < 1 or col > 12:
        raise ValueError(f"Column out of range in well identifier: {well}")
    row_idx = ord(row_char) - ord('A')
    col_idx = col - 1
    return row_idx, col_idx


def _build_plate_mapping(num_ligand: int, num_salt: int, replicates: int) -> Dict[Tuple[int, int], Tuple[int, int]]:
    """Map (row_idx, col_idx) -> (ligand_index, salt_index) for a 96-well plate.

    Ligand index: position along the column, 0..num_ligand-1 starting at row A.
    Salt index: groups of replicates along the row direction of column index, 0..num_salt-1.
    """
    mapping: Dict[Tuple[int, int], Tuple[int, int]] = {}
    if num_ligand > 8:
        raise ValueError("Number of ligand concentrations cannot exceed 8 (plate rows).")

    total_wells_per_row = 12
    wells_per_salt = replicates
    if wells_per_salt <= 0:
        raise ValueError("Replicates must be positive.")
    max_salt_positions = total_wells_per_row // wells_per_salt
    if num_salt > max_salt_positions:
        raise ValueError(
            f"Number of salt concentrations ({num_salt}) with {replicates} replicates each "
            f"exceeds number of columns (12)."
        )

    for row_idx in range(num_ligand):
        for salt_index in range(num_salt):
            for rep in range(replicates):
                col_idx = salt_index * replicates + rep
                if col_idx >= total_wells_per_row:
                    continue
                mapping[(row_idx, col_idx)] = (row_idx, salt_index)

    return mapping


def _invert_calibration(absorbance: np.ndarray, slope: float, intercept: float) -> np.ndarray:
    """Invert calibration curve to get concentration from absorbance.

    cE = (Absorbance - intercept) / slope
    """
    if slope == 0:
        raise ValueError("Calibration slope is zero; cannot invert calibration.")
    return (absorbance - intercept) / slope


def _parse_semicolon_floats(text: str) -> List[float]:
    """Parse a semicolon-separated string into list of floats, handling commas as decimal separators."""
    if text is None:
        raise ValueError("Expected semicolon-separated string, got None")
    parts = [p.strip() for p in str(text).split(';') if p.strip() != ""]
    values: List[float] = []
    for p in parts:
        p_norm = p.replace(',', '.')
        try:
            values.append(float(p_norm))
        except ValueError:
            raise ValueError(f"Cannot convert value '{p}' to float in semicolon-separated list")
    return values


def _safe_float(value: Any, field_name: str) -> float:
    try:
        v = str(value).replace(',', '.')
        return float(v)
    except Exception:
        raise ValueError(f"Metadata field '{field_name}' must be numeric; got {value!r}")


def _get_experiment_json(experiment_id: str, data_folder: str) -> Dict[str, Any]:
    """Load experiment JSON with fallback to root path as required."""
    root_first = Path('../') / f'experiment_{experiment_id}.json'
    data_path = root_first
    if not data_path.exists():
        data_path = Path(data_folder) / f'experiment_{experiment_id}.json'

    if not data_path.exists():
        raise FileNotFoundError(f"Data file not found: {data_path}")

    try:
        with open(data_path, 'r') as f:
            experiment_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format in {data_path}: {e}")

    return experiment_data


def _extract_metadata(experiment_data: Dict[str, Any]) -> Dict[str, Any]:
    """Extract required metadata fields from experiment JSON with validation."""
    try:
        metadata = experiment_data['metadata_decoded']['extra_fields']
    except KeyError as e:
        raise KeyError(f"Missing expected metadata structure: {e}")

    required_fields = [
        'Number of ligand concentrations',
        'Number of salt concentrations',
        'Replicates',
        'Ligand concentrations',
        'Salt concentrations',
        'Ligand concentration unit',
        'Salt concentration unit',
        'Calibration Curve Slope',
        'Calibration Curve Intercept',
        'Resin Mass',
        'Total volume',
    ]

    meta_out: Dict[str, Any] = {}

    for field in required_fields:
        if field not in metadata:
            raise KeyError(f"Missing expected metadata field: {field}")
        if 'value' not in metadata[field]:
            raise KeyError(f"Metadata field '{field}' has no 'value' entry")
        meta_out[field] = metadata[field]['value']

    num_ligand = int(_safe_float(meta_out['Number of ligand concentrations'], 'Number of ligand concentrations'))
    num_salt = int(_safe_float(meta_out['Number of salt concentrations'], 'Number of salt concentrations'))
    replicates = int(_safe_float(meta_out['Replicates'], 'Replicates'))

    ligand_concs = _parse_semicolon_floats(meta_out['Ligand concentrations'])
    salt_concs = _parse_semicolon_floats(meta_out['Salt concentrations'])

    if len(ligand_concs) != num_ligand:
        raise ValueError(
            f"Number of ligand concentrations ({num_ligand}) does not match length of list in metadata ({len(ligand_concs)})."
        )
    if len(salt_concs) != num_salt:
        raise ValueError(
            f"Number of salt concentrations ({num_salt}) does not match length of list in metadata ({len(salt_concs)})."
        )

    slope = _safe_float(meta_out['Calibration Curve Slope'], 'Calibration Curve Slope')
    intercept = _safe_float(meta_out['Calibration Curve Intercept'], 'Calibration Curve Intercept')
    resin_mass = _safe_float(meta_out['Resin Mass'], 'Resin Mass')
    total_volume = _safe_float(meta_out['Total volume'], 'Total volume')

    ligand_unit = str(meta_out['Ligand concentration unit'])
    salt_unit = str(meta_out['Salt concentration unit'])

    return {
        'num_ligand': num_ligand,
        'num_salt': num_salt,
        'replicates': replicates,
        'ligand_concs': ligand_concs,
        'salt_concs': salt_concs,
        'ligand_unit': ligand_unit,
        'salt_unit': salt_unit,
        'slope': slope,
        'intercept': intercept,
        'resin_mass_mg': resin_mass,
        'total_volume_uL': total_volume,
    }


def _fetch_single_tecan_excel(experiment_id: str, results_folder_path: Path, analysis_results: Dict[str, Any]) -> Path:
    """Fetch a single Tecan Excel file from device server or local fallback."""
    print(f"Fetching Tecan data for experiment {experiment_id} from device control server...")

    try:
        data_info = check_tecan_data_availability(experiment_id)
        if not data_info.get("available", False):
            raise FileNotFoundError(f"No Tecan data available for experiment {experiment_id}: {data_info.get('error', 'Unknown error')}")

        print(f"Tecan data found on server: {data_info.get('total_files', 0)} file(s)")
        tecan_data_path_str = fetch_tecan_data_file(experiment_id, str(results_folder_path))
        return Path(tecan_data_path_str)

    except Exception as device_server_error:
        print(f"Device control server access failed: {device_server_error}. Falling back to local file search...")
        tecan_raw_path = "C:/Users/Public/Documents/Tecan/SparkControl/Workspaces"

        if not Path(tecan_raw_path).exists():
            analysis_results["message"] = "Tecan data not available - analysis skipped. This is expected for test runs."
            analysis_results["status"] = "success"
            analysis_results["note"] = "No Tecan data found on server or local system."
            print(f"INFO: {analysis_results['message']}")
            return None

        most_recent_excel_source = get_most_recent_excel_file(tecan_raw_path)
        if not most_recent_excel_source:
            analysis_results["message"] = "No recent Tecan Excel file found - analysis skipped."
            analysis_results["status"] = "success"
            print(f"INFO: {analysis_results['message']}")
            return None

        tecan_data_path = results_folder_path / f'tecan_data_{experiment_id}.xlsx'
        shutil.copy(most_recent_excel_source, tecan_data_path)
        print(f"Raw data copied from '{most_recent_excel_source}' to '{tecan_data_path}'")
        return tecan_data_path


def _read_absorbance_grid_from_excel(excel_path: Path) -> np.ndarray:
    """Read absorbance data (8x12) from Tecan Excel file.

    Data starts at row 34 (0-based skiprows=33) and column B (index 1).
    """
    print(f"Reading absorbance data from Excel file: {excel_path}")
    try:
        df = pd.read_excel(
            excel_path,
            header=None,
            skiprows=33,
            usecols=list(range(1, 13)),
            nrows=8,
        )
    except Exception as e:
        raise RuntimeError(f"Failed to read absorbance data from Excel file {excel_path}: {e}")

    data = df.to_numpy(dtype=float)
    if data.shape != (8, 12):
        print(f"WARNING: Expected absorbance grid shape (8,12), got {data.shape}. Proceeding with available data.")
    return data


def _prepare_condition_table(abs_grid: np.ndarray, meta: Dict[str, Any]) -> pd.DataFrame:
    """Prepare per-well table with mapping to ligand and salt conditions and compute cE.

    Returns a DataFrame with columns:
      row_idx, col_idx, well, ligand_index, salt_index, c0, salt_conc, absorbance, cE
    """
    num_ligand = meta['num_ligand']
    num_salt = meta['num_salt']
    replicates = meta['replicates']
    ligand_concs = meta['ligand_concs']
    salt_concs = meta['salt_concs']
    slope = meta['slope']
    intercept = meta['intercept']

    plate_mapping = _build_plate_mapping(num_ligand, num_salt, replicates)

    records: List[Dict[str, Any]] = []

    for row_idx in range(abs_grid.shape[0]):
        for col_idx in range(abs_grid.shape[1]):
            key = (row_idx, col_idx)
            if key not in plate_mapping:
                continue
            ligand_index, salt_index = plate_mapping[key]
            if ligand_index >= len(ligand_concs) or salt_index >= len(salt_concs):
                continue
            c0 = ligand_concs[ligand_index]
            salt_c = salt_concs[salt_index]
            absorb = abs_grid[row_idx, col_idx]
            try:
                cE = _invert_calibration(absorb, slope, intercept)
            except Exception as e:
                raise RuntimeError(f"Calibration inversion failed for well ({row_idx},{col_idx}): {e}")

            row_char = chr(ord('A') + row_idx)
            well = f"{row_char}{col_idx + 1}"

            records.append({
                'row_idx': row_idx,
                'col_idx': col_idx,
                'well': well,
                'ligand_index': ligand_index,
                'salt_index': salt_index,
                'c0': c0,
                'salt_conc': salt_c,
                'absorbance': absorb,
                'cE': cE,
            })

    df = pd.DataFrame.from_records(records)

    expected_groups = meta['num_ligand'] * meta['num_salt']
    actual_groups = df.groupby(['ligand_index', 'salt_index']).size()
    if actual_groups.size != expected_groups:
        raise RuntimeError(
            f"Well-to-condition mapping error: expected {expected_groups} groups "
            f"(num_ligand x num_salt), but found {actual_groups.size}."
        )

    max_c0 = max(ligand_concs) if ligand_concs else 0.0
    if max_c0 <= 0:
        raise ValueError("Maximum initial ligand concentration c0 must be positive for sanity checks.")

    if (df['cE'] < 0).any() or (df['cE'] > max_c0 + 1e-9).any():
        raise RuntimeError(
            "Calibration sanity check failed: some equilibrium concentrations cE are outside [0, max(c0)]. "
            "Check calibration slope and intercept."
        )

    for salt_index in range(num_salt):
        sub = df[df['salt_index'] == salt_index]
        if sub.empty:
            continue
        std_cE = sub['cE'].std()
        if std_cE < 1e-6:
            print(
                f"WARNING: Very low variation in cE across column for salt_index {salt_index}. "
                f"Check that calibration has been applied correctly."
            )

    return df


def _aggregate_replicates(df: pd.DataFrame, meta: Dict[str, Any]) -> pd.DataFrame:
    """Aggregate replicates to get mean and std of cE and compute loading q.

    Returns DataFrame with columns:
      ligand_index, salt_index, c0, salt_conc, cE_mean, cE_std, q_mean, q_std, n
    """
    resin_mass_mg = meta['resin_mass_mg']
    total_volume_uL = meta['total_volume_uL']

    if resin_mass_mg <= 0 or total_volume_uL <= 0:
        raise ValueError("Resin mass and total volume must be positive for q calculation.")

    grouped = df.groupby(['ligand_index', 'salt_index', 'c0', 'salt_conc'])
    agg = grouped['cE'].agg(['mean', 'std', 'count']).reset_index()
    agg.rename(columns={'mean': 'cE_mean', 'std': 'cE_std', 'count': 'n'}, inplace=True)

    expected_groups = meta['num_ligand'] * meta['num_salt']
    if len(agg) != expected_groups:
        raise RuntimeError(
            f"Aggregate group count mismatch: expected {expected_groups}, got {len(agg)}. "
            "Check plate layout and mapping."
        )

    replicates = meta['replicates']
    if (agg['n'] != replicates).any():
        raise RuntimeError(
            f"Replicate count mismatch: expected {replicates} per condition, "
            f"but got values {sorted(agg['n'].unique())}."
        )

    agg['q_mean'] = (agg['c0'] - agg['cE_mean']) * total_volume_uL / resin_mass_mg

    q_single = (df['c0'] - df['cE']) * total_volume_uL / resin_mass_mg
    df = df.copy()
    df['q'] = q_single
    q_stats = df.groupby(['ligand_index', 'salt_index'])['q'].agg(['std']).reset_index()
    q_stats.rename(columns={'std': 'q_std'}, inplace=True)
    agg = pd.merge(agg, q_stats, on=['ligand_index', 'salt_index'], how='left')

    agg['q_std'] = agg['q_std'].fillna(0.0)

    return agg


def _r2_score(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    """Calculate coefficient of determination R^2 manually."""
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    ss_res = np.sum((y_true - y_pred) ** 2)
    ss_tot = np.sum((y_true - np.mean(y_true)) ** 2)
    if ss_tot == 0:
        return float('nan')
    return 1 - ss_res / ss_tot


def _fit_langmuir_isotherms(agg: pd.DataFrame, meta: Dict[str, Any], experiment_id: str, results_folder_path: Path) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """Fit Langmuir isotherms per salt concentration.

    Returns:
      - DataFrame with fitted parameters per salt concentration
      - Dict of fit diagnostics
    """
    salt_indices = sorted(agg['salt_index'].unique())
    salt_concs = meta['salt_concs']
    results_records: List[Dict[str, Any]] = []
    fit_info: Dict[str, Any] = {}

    for salt_index in salt_indices:
        sub = agg[agg['salt_index'] == salt_index].copy()
        if sub.empty:
            continue

        c_e = sub['cE_mean'].to_numpy(dtype=float)
        q_obs = sub['q_mean'].to_numpy(dtype=float)

        finite_mask = np.isfinite(c_e) & np.isfinite(q_obs)
        c_e = c_e[finite_mask]
        q_obs = q_obs[finite_mask]

        if c_e.size < 3:
            print(f"WARNING: Not enough points to fit Langmuir isotherm for salt_index {salt_index}.")
            continue

        q_max_guess = float(np.max(q_obs)) if np.isfinite(np.max(q_obs)) else 1.0
        mid_q = np.median(q_obs)
        try:
            c_mid = float(c_e[np.argsort(np.abs(q_obs - mid_q))[0]])
        except Exception:
            c_mid = float(np.median(c_e)) if np.isfinite(np.median(c_e)) else 1.0
        k_a_guess = 1.0 / max(c_mid, 1e-9)

        p0 = [q_max_guess, k_a_guess]
        bounds = ([0.0, 0.0], [np.inf, np.inf])

        try:
            popt, pcov = curve_fit(_langmuir_isotherm, c_e, q_obs, p0=p0, bounds=bounds, maxfev=10000)
            q_pred = _langmuir_isotherm(c_e, *popt)
            r2 = _r2_score(q_obs, q_pred)
        except Exception as e:
            print(f"WARNING: Langmuir fit failed for salt_index {salt_index}: {e}")
            continue

        q_max, k_a = popt
        if not (np.isfinite(q_max) and np.isfinite(k_a)):
            print(f"WARNING: Non-finite Langmuir parameters for salt_index {salt_index}; skipping.")
            continue

        if q_max <= 0 or k_a < 0:
            print(f"WARNING: Unphysical Langmuir parameters for salt_index {salt_index}: q_max={q_max}, k_a={k_a}")

        results_records.append({
            'salt_index': salt_index,
            'salt_conc': salt_concs[salt_index] if salt_index < len(salt_concs) else np.nan,
            'q_max': q_max,
            'K': k_a,
            'R2': r2,
        })

        fit_info[f'salt_{salt_index}'] = {
            'salt_conc': salt_concs[salt_index] if salt_index < len(salt_concs) else None,
            'q_max': float(q_max),
            'K': float(k_a),
            'R2': float(r2),
            'num_points': int(c_e.size),
        }

    if not results_records:
        raise RuntimeError("Langmuir fitting failed for all salt concentrations.")

    fit_df = pd.DataFrame.from_records(results_records)

    fit_params_csv = results_folder_path / f'langmuir_fit_parameters_{experiment_id}.csv'
    fit_df.to_csv(fit_params_csv, index=False)
    print(f"Saved Langmuir fit parameters to: {fit_params_csv}")

    return fit_df, fit_info


def _plot_isotherms(agg: pd.DataFrame, fit_df: pd.DataFrame, meta: Dict[str, Any], experiment_id: str, results_folder_path: Path) -> Dict[str, str]:
    """Plot all isotherms (data + fits) in one graph.

    Returns dict with paths to created plot files.
    """
    ligand_unit = meta['ligand_unit']
    salt_unit = meta['salt_unit']

    fig, ax = plt.subplots(figsize=(8, 6))

    cmap = plt.get_cmap('viridis')
    salt_indices = sorted(agg['salt_index'].unique())
    n_salts = len(salt_indices)

    for i, salt_index in enumerate(salt_indices):
        color = cmap(float(i) / max(n_salts - 1, 1))
        sub = agg[agg['salt_index'] == salt_index]
        salt_conc = sub['salt_conc'].iloc[0]

        ax.errorbar(
            sub['cE_mean'],
            sub['q_mean'],
            yerr=sub['q_std'],
            fmt='o',
            color=color,
            label=None,
            capsize=3,
            markersize=4,
        )

        fit_row = fit_df[fit_df['salt_index'] == salt_index]
        if not fit_row.empty:
            q_max = fit_row['q_max'].iloc[0]
            K = fit_row['K'].iloc[0]
            R2 = fit_row['R2'].iloc[0]
            c_min = max(0.0, sub['cE_mean'].min())
            c_max = max(sub['cE_mean'].max(), c_min + 1e-9)
            c_grid = np.linspace(c_min, c_max, 100)
            q_fit = _langmuir_isotherm(c_grid, q_max, K)
            label = (
                f"Salt {salt_conc:g} {salt_unit} | q_max={q_max:.3g}, K={K:.3g}, R2={R2:.3f}"
            )
            ax.plot(c_grid, q_fit, '-', color=color, label=label)
        else:
            print(f"WARNING: No fit parameters found for salt_index {salt_index} while plotting.")

    ax.set_xlabel(f"Equilibrium ligand concentration cE [{ligand_unit}]")
    ax.set_ylabel(f"Loading q [{ligand_unit} * uL / mg]")
    ax.set_title("Loading isotherms from Tecan plate reader")
    ax.legend(fontsize=8)
    ax.grid(True, linestyle='--', linewidth=0.5, alpha=0.5)

    fig.tight_layout()

    png_path = results_folder_path / f'isotherms_{experiment_id}.png'
    pdf_path = results_folder_path / f'isotherms_{experiment_id}.pdf'
    fig.savefig(png_path, dpi=300)
    fig.savefig(pdf_path)
    plt.close(fig)

    print(f"Saved isotherm plots to: {png_path} and {pdf_path}")

    return {
        'isotherms_png': str(png_path.resolve()),
        'isotherms_pdf': str(pdf_path.resolve()),
    }


def analyze_experiment(experiment_id=None, data_folder='../data', results_folder='../results'):
    """Main analysis function for Tecan plate reader loading isotherm experiments.

    Args:
        experiment_id (str): Experiment ID for data linking. If None, tries to auto-detect.
        data_folder (str): Path to the folder containing experiment_ID.json files.
        results_folder (str): Path to the folder where all analysis outputs will be saved.

    Returns:
        dict: Analysis results with all key metrics and paths to generated files.
    """
    results_folder_path = Path(results_folder)
    results_folder_path.mkdir(parents=True, exist_ok=True)

    if experiment_id is None:
        if len(sys.argv) > 1 and sys.argv[1] not in ('', None):
            experiment_id = sys.argv[1]
        else:
            data_path = Path(data_folder)
            if not data_path.exists():
                raise FileNotFoundError(f"Data folder does not exist and no experiment_id provided: {data_folder}")
            json_files = sorted(
                data_path.glob('experiment_*.json'),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            if not json_files:
                raise FileNotFoundError("No experiment_*.json files found for auto-detection of experiment_id.")
            latest = json_files[0]
            name = latest.stem
            prefix = "experiment_"
            if not name.startswith(prefix):
                raise ValueError(f"Cannot parse experiment id from filename: {latest}")
            experiment_id = name[len(prefix):]
            print(f"INFO: Auto-detected experiment_id {experiment_id} from most recent JSON file {latest}")

    analysis_results: Dict[str, Any] = {
        "experiment_id": experiment_id,
        "status": "failed",
        "message": "",
        "plots": {},
        "data_outputs": {},
        "metadata": {},
        "files_processed": 0,
    }

    try:
        experiment_data = _get_experiment_json(experiment_id, data_folder)
        print(f"Loaded experiment JSON for ID {experiment_id}")
    except Exception as e:
        analysis_results["message"] = str(e)
        print(f"ERROR: {e}")
        return analysis_results

    try:
        meta = _extract_metadata(experiment_data)
        analysis_results['metadata'].update(meta)
        print("Extracted metadata from experiment JSON")
    except Exception as e:
        analysis_results["message"] = f"Metadata extraction failed: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    tecan_excel_path = _fetch_single_tecan_excel(experiment_id, results_folder_path, analysis_results)
    if tecan_excel_path is None:
        if analysis_results.get("status") != "success":
            analysis_results["status"] = "success"
        return analysis_results

    analysis_results['data_outputs']['raw_tecan_excel'] = str(tecan_excel_path.resolve())

    try:
        abs_grid = _read_absorbance_grid_from_excel(tecan_excel_path)
        analysis_results['files_processed'] += 1
    except Exception as e:
        analysis_results["message"] = f"Failed to read Tecan Excel data: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    try:
        per_well_df = _prepare_condition_table(abs_grid, meta)
    except Exception as e:
        analysis_results["message"] = f"Per-well processing failed: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    per_well_csv = results_folder_path / f'per_well_data_{experiment_id}.csv'
    per_well_df.to_csv(per_well_csv, index=False)
    analysis_results['data_outputs']['per_well_csv'] = str(per_well_csv.resolve())
    print(f"Saved per-well processed data to: {per_well_csv}")

    try:
        agg_df = _aggregate_replicates(per_well_df, meta)
    except Exception as e:
        analysis_results["message"] = f"Aggregation of replicates failed: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    agg_csv = results_folder_path / f'aggregated_isotherm_data_{experiment_id}.csv'
    agg_df.to_csv(agg_csv, index=False)
    analysis_results['data_outputs']['aggregated_csv'] = str(agg_csv.resolve())
    print(f"Saved aggregated isotherm data to: {agg_csv}")

    try:
        fit_df, fit_info = _fit_langmuir_isotherms(agg_df, meta, experiment_id, results_folder_path)
        analysis_results['metadata']['langmuir_fits'] = fit_info
        analysis_results['data_outputs']['fit_parameters_csv'] = str(
            (results_folder_path / f'langmuir_fit_parameters_{experiment_id}.csv').resolve()
        )
    except Exception as e:
        analysis_results["message"] = f"Langmuir fitting failed: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    try:
        plot_paths = _plot_isotherms(agg_df, fit_df, meta, experiment_id, results_folder_path)
        analysis_results['plots'].update(plot_paths)
    except Exception as e:
        analysis_results["message"] = f"Plotting failed: {e}"
        print(f"ERROR: {analysis_results['message']}")
        return analysis_results

    analysis_results["status"] = "success"
    analysis_results["message"] = "Analysis completed successfully."

    results_json_file = f"analysis_results_{experiment_id}.json"
    results_json_path = results_folder_path / results_json_file
    with open(results_json_path, 'w') as f:
        json.dump(analysis_results, f, indent=4)
    print(f"Saved analysis results JSON to: {results_json_path}")

    return analysis_results


def main():
    """Command line interface"""
    parser = argparse.ArgumentParser(description='Analyze Tecan plate reader loading isotherm experiment data.')
    parser.add_argument('experiment_id', nargs='?', help='Experiment ID. If not provided, attempts to auto-detect the most recent.')
    parser.add_argument('--data-folder', default='../data', help='Path to the folder containing experiment_ID.json files. Default: ../data')
    parser.add_argument('--results-folder', default='../results', help='Path to the folder where all analysis outputs will be saved. Default: ../results')

    args = parser.parse_args()

    try:
        results = analyze_experiment(
            experiment_id=args.experiment_id,
            data_folder=args.data_folder,
            results_folder=args.results_folder
        )
        if results["status"] == "success":
            print("Analysis successful!")
            return 0
        else:
            print(f"Analysis failed: {results.get('message', 'Unknown error.')}")
            return 1
    except Exception as e:
        print(f"An unhandled error occurred during analysis: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())
